-- name: CreateDataset :one
-- The id is generated by the caller so source files can be streamed to their
-- final storage key before any rows are written.
INSERT INTO datasets (id, workspace_id, name, description, created_by)
VALUES ($1, $2, $3, $4, $5)
RETURNING *;

-- name: GetDatasetByID :one
SELECT * FROM datasets WHERE id = $1;

-- name: CreateDatasetVersion :one
INSERT INTO dataset_versions (
    dataset_id, version_no, file_format, original_name,
    byte_size, checksum_sha256, source_path, status
)
VALUES ($1, $2, $3, $4, $5, $6, $7, 'queued')
RETURNING *;

-- name: GetDatasetWithAccess :one
SELECT d.*
FROM datasets d
JOIN workspace_members m ON m.workspace_id = d.workspace_id
WHERE d.id = $1 AND m.user_id = $2 AND d.deleted_at IS NULL;

-- name: ListWorkspaceDatasets :many
SELECT d.*
FROM datasets d
JOIN workspace_members m ON m.workspace_id = d.workspace_id
WHERE d.workspace_id = $1 AND m.user_id = $2
ORDER BY d.created_at DESC;

-- name: CountWorkspaceDatasets :one
SELECT count(*) FROM datasets WHERE workspace_id = $1;

-- name: ListWorkspaceDatasetSummaries :many
-- One row per dataset with its current version and profile quality. The
-- current version always exists: it is created in the same transaction as the
-- dataset.
SELECT d.id, d.workspace_id, d.name, d.description, d.current_version_no,
       d.created_at, d.updated_at,
       v.id AS version_id, v.version_no, v.status, v.file_format, v.original_name,
       v.row_count, v.column_count, v.byte_size, v.parquet_path,
       v.error_code, v.error_message, v.updated_at AS version_updated_at,
       p.quality_score
FROM datasets d
JOIN workspace_members m ON m.workspace_id = d.workspace_id AND m.user_id = $2
JOIN dataset_versions v ON v.dataset_id = d.id AND v.version_no = d.current_version_no
LEFT JOIN dataset_profiles p ON p.version_id = v.id
WHERE d.workspace_id = $1 AND d.deleted_at IS NULL
ORDER BY d.created_at DESC;

-- name: GetDatasetSummary :one
SELECT d.id, d.workspace_id, d.name, d.description, d.current_version_no,
       d.created_at, d.updated_at,
       v.id AS version_id, v.version_no, v.status, v.file_format, v.original_name,
       v.row_count, v.column_count, v.byte_size, v.parquet_path,
       v.error_code, v.error_message, v.updated_at AS version_updated_at,
       p.quality_score
FROM datasets d
JOIN workspace_members m ON m.workspace_id = d.workspace_id AND m.user_id = $2
JOIN dataset_versions v ON v.dataset_id = d.id AND v.version_no = d.current_version_no
LEFT JOIN dataset_profiles p ON p.version_id = v.id
WHERE d.id = $1 AND m.user_id = $2 AND d.deleted_at IS NULL;

-- name: GetDatasetVersion :one
SELECT * FROM dataset_versions
WHERE id = $1;

-- name: GetDatasetVersionByNo :one
SELECT * FROM dataset_versions
WHERE dataset_id = $1 AND version_no = $2;

-- name: GetLatestDatasetVersion :one
SELECT * FROM dataset_versions
WHERE dataset_id = $1
ORDER BY version_no DESC
LIMIT 1;

-- name: GetLatestDatasetVersionForUpdate :one
SELECT * FROM dataset_versions
WHERE dataset_id = $1
ORDER BY version_no DESC
LIMIT 1
FOR UPDATE;

-- name: MarkDatasetVersionProcessing :one
UPDATE dataset_versions
SET status = 'processing',
    error_code = NULL,
    error_message = NULL,
    updated_at = now()
WHERE id = $1
RETURNING *;

-- name: MarkDatasetVersionReady :one
UPDATE dataset_versions
SET status = 'ready',
    row_count = $2,
    column_count = $3,
    parquet_path = $4,
    parquet_sha256 = $5,
    processing_report = $6,
    error_code = NULL,
    error_message = NULL,
    updated_at = now()
WHERE id = $1
RETURNING *;

-- name: MarkDatasetVersionFailed :one
UPDATE dataset_versions
SET status = 'failed',
    error_code = $2,
    error_message = $3,
    updated_at = now()
WHERE id = $1
RETURNING *;

-- name: InsertDatasetColumn :one
INSERT INTO dataset_columns (
    version_id, column_name, original_name, inferred_type, is_nullable, column_order
)
VALUES ($1, $2, $3, $4, $5, $6)
RETURNING *;

-- name: ListDatasetColumns :many
SELECT * FROM dataset_columns
WHERE version_id = $1
ORDER BY column_order;

-- name: UpsertDatasetProfile :one
INSERT INTO dataset_profiles (version_id, profile_json, quality_score)
VALUES ($1, $2, $3)
ON CONFLICT (version_id) DO UPDATE
SET profile_json = EXCLUDED.profile_json,
    quality_score = EXCLUDED.quality_score
RETURNING *;

-- name: GetDatasetProfile :one
SELECT * FROM dataset_profiles
WHERE version_id = $1;

-- name: UpdateDatasetCurrentVersion :one
UPDATE datasets
SET current_version_no = $2,
    updated_at = now()
WHERE id = $1
RETURNING *;

-- name: RenameDataset :one
-- Membership is checked in-query so a non-member gets the same "not found".
UPDATE datasets d
SET name = $3,
    updated_at = now()
FROM workspace_members m
WHERE d.id = $1
  AND m.workspace_id = d.workspace_id
  AND m.user_id = $2
  AND d.deleted_at IS NULL
RETURNING d.*;

-- name: SoftDeleteDataset :one
-- Soft delete keeps the rows for the grace period; the purge janitor removes
-- the files and cascades the rows once purge_after passes.
UPDATE datasets d
SET deleted_at = now(),
    purge_after = now() + make_interval(days => $3),
    updated_at = now()
FROM workspace_members m
WHERE d.id = $1
  AND m.workspace_id = d.workspace_id
  AND m.user_id = $2
  AND d.deleted_at IS NULL
RETURNING d.*;

-- name: GetDatasetForUpdate :one
-- Locks the dataset row so two concurrent reprocess calls serialize.
SELECT d.* FROM datasets d
JOIN workspace_members m ON m.workspace_id = d.workspace_id AND m.user_id = $2
WHERE d.id = $1 AND d.deleted_at IS NULL
FOR UPDATE OF d;

-- name: ListPurgeDue :many
SELECT * FROM datasets
WHERE deleted_at IS NOT NULL AND purge_after <= now()
ORDER BY purge_after
LIMIT $1;

-- name: PurgeDataset :exec
DELETE FROM datasets WHERE id = $1;

-- name: ListDatasetVersions :many
SELECT * FROM dataset_versions
WHERE dataset_id = $1
ORDER BY version_no;

-- name: ListDatasetVersionsBeyondRetention :many
-- Everything past the newest $2 versions, oldest first, for file-first cleanup.
SELECT * FROM dataset_versions
WHERE dataset_id = $1
ORDER BY version_no DESC
OFFSET $2;

-- name: DeleteDatasetVersion :exec
DELETE FROM dataset_versions WHERE id = $1;
